foreach(['confirmed'=>1,'requested'=>1,'history'=>[['note'=>'Contacto']],'notes'=>'Pendiente','next'=>'2099-01-01','status'=>'Interesada'] as $k=>$v){$x=$d;$x['links'][$c]['T1'][$k]=$v;check((bool)company_remove_blockers($x,$c,'T1',true),'protege '.$k);}
foreach(['students','docs','campaigns','inbox','accounts','invites','interest_evidence','campaign_permissions'] as $k){$x=$d;switch($k){case 'students':$x[$k][$c]['A01']['company']='T1';break;case 'docs':$x[$k]['D']=['course'=>$c,'company'=>'T1'];break;case 'campaigns':$x[$k]['C']=['course'=>$c,'rows'=>['T1'=>[]]];break;case 'inbox':$x[$k]['M']=['course'=>$c,'link'=>'T1'];break;case 'interest_evidence':$x[$k]['I']=['company'=>'T1','course'=>$c,'group'=>$g];break;case 'campaign_permissions':$x[$k]['T1']['test@example.org']=['allowed'=>true];break;default:$x[$k]['X']=['company'=>'T1'];}check((bool)company_remove_blockers($x,$c,'T1',true),'protege '.$k);}
$d['links'][$c]['T1~second']=imp_link('g2');check((bool)company_remove_blockers($d,$c,'T1',true),'no borra ficha vinculada a otro grupo');company_remove($d,$c,'T1',false);check(isset($d['companies']['T1'],$d['links'][$c]['T1~second'])&&!isset($d['links'][$c]['T1']),'retira solo colaboración elegida');company_remove($d,$c,'T1~second',true);check(!isset($d['companies']['T1'],$d['links'][$c]['T1~second'])&&count($d['audit'])===2,'eliminación completa registra auditoría');
